$(function(){$('.sort-switch').each(function(){const $sortBtn=$(this);const $playlistContainer=$sortBtn.closest('.stui-pannel').find('.playlist-container');const $playlistItems=$playlistContainer.find('li');let currentSort='asc';$sortBtn.on('click',function(){currentSort=currentSort==='asc'?'desc':'asc';if(currentSort==='asc'){$sortBtn.html('<i class="glyphicon glyphicon-sort-by-attributes"></i> 正序');$sortBtn.data('sort','asc')}else{$sortBtn.html('<i class="glyphicon glyphicon-sort-by-attributes-alt"></i> 倒序');$sortBtn.data('sort','desc')}const itemsArray=Array.from($playlistItems);itemsArray.sort(function(a,b){const nidA=parseInt($(a).data('nid'));const nidB=parseInt($(b).data('nid'));return currentSort==='asc'?(nidA-nidB):(nidB-nidA)});$playlistContainer.empty().append(itemsArray)})});$('.stui-player__list li a').on('click',function(){setTimeout(function(){const $activePanel=$('.stui-pannel:visible');const $activeSortBtn=$activePanel.find('.sort-switch');if($activeSortBtn.data('sort')!=='asc'){$activeSortBtn.html('<i class="glyphicon glyphicon-sort-by-attributes"></i> 正序');$activeSortBtn.data('sort','asc');const $playlistContainer=$activePanel.find('.playlist-container');const $playlistItems=$playlistContainer.find('li');const itemsArray=Array.from($playlistItems);itemsArray.sort(function(a,b){const nidA=parseInt($(a).data('nid'));const nidB=parseInt($(b).data('nid'));return nidA-nidB});$playlistContainer.empty().append(itemsArray)}},100)})});